  `token` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `people`;
CREATE TABLE `people` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `gender` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `alias` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `marga_id` bigint unsigned DEFAULT NULL,
  `province_code` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `regency_code` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `district_code` varchar(15) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `village_code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` bigint unsigned DEFAULT NULL,
  `father_id` bigint unsigned DEFAULT NULL,
  `pending_father` tinyint(1) NOT NULL DEFAULT '0',
  `is_public` tinyint(1) NOT NULL DEFAULT '0',
  `birth_order` int unsigned DEFAULT NULL,
  `sibling_count` int unsigned DEFAULT NULL,
  `chain` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mother_id` bigint unsigned DEFAULT NULL,
  `birth_year` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `death_year` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `image` text COLLATE utf8mb4_unicode_ci,
  `bio` text COLLATE utf8mb4_unicode_ci,
  `related_stories` json DEFAULT NULL,
  `spouse` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `spouse_marga` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `people_marga_id_foreign` (`marga_id`),
  KEY `people_parent_id_foreign` (`father_id`),
  KEY `people_mother_id_foreign` (`mother_id`),
  KEY `people_created_by_foreign` (`created_by`),
  KEY `people_chain_index` (`chain`),
  KEY `people_is_public_index` (`is_public`),
  CONSTRAINT `people_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `people_marga_id_foreign` FOREIGN KEY (`marga_id`) REFERENCES `margas` (`id`) ON DELETE SET NULL,
  CONSTRAINT `people_mother_id_foreign` FOREIGN KEY (`mother_id`) REFERENCES `people` (`id`) ON DELETE SET NULL,
  CONSTRAINT `people_parent_id_foreign` FOREIGN KEY (`father_id`) REFERENCES `people` (`id`) ON DELETE SET NULL
