  CONSTRAINT `person_wife_husband_id_foreign` FOREIGN KEY (`husband_id`) REFERENCES `people` (`id`) ON DELETE CASCADE,
  CONSTRAINT `person_wife_wife_id_foreign` FOREIGN KEY (`wife_id`) REFERENCES `people` (`id`) ON DELETE CASCADE
