INSERT INTO `stories` (`id`, `created_by`, `marga_id`, `classification`, `title`, `description`, `image`, `content_url`, `published`, `status`, `review_version`, `reviewed_by`, `reviewed_at`, `rejection_reason`, `created_at`, `updated_at`) VALUES
(1, NULL, NULL, 'umum', 'Asal Usul Marga Sitorus', 'Legenda tentang Ompu Sitorus dan permulaan keturunannya di Tanah Batak.', 'https://lh3.googleusercontent.com/aida-public/AB6AXuDvxKrNEUUzGkHRdPPRefpFd2nx2aji_7DCjpPgj_B3GXNjx112a-pr5A4HPfXOtnk_KQ1Bv3bNDiy4REOFLHMNEkl6sOZYjNVUnuo3OQB2as_A8qWSJrMq1ylc-7dOs7t32J2jdha2lwZnzjrZvJ0Ujnti3jKarNC2onQXNi3qoUhp8MWXBEnIwoUfmImM_k9ajcibnvfGaq6BQdjdPZLQNAlwdG55pO3b37KTlg3PuxJGXsJ7l58', NULL, 1, 'approved', 1, NULL, NULL, NULL, '2026-08-05 16:50:51', '2026-08-05 16:50:51'),
(2, NULL, NULL, 'umum', 'Makna Gorga dan Simbol Batak', 'Memahami arti di balik setiap ukiran dan motif dalam budaya Batak.', 'https://lh3.googleusercontent.com/aida-public/AB6AXuCmmQd3_QG70w7ItlibgZCh2ZBdnTYCbZoHOL-1MuSxYIL97h81V6coS5gyYM6j4Xwmk2Bbi87whN-RhJyoH7XpUPF8ekbjWQEnmoWnq77cqcaGid30OR7VBSvfrcbFKDyx_ztqpj-YsD7_vn5O1rd4V2jhKPC0eaFFssJyvRBAS5Wj8MF_n7tkoYbIS1WZmMj1z8eoxBRU3Duq8p_xvymVvO3IwRWcH4WSNVYZJeWo1gpShlhIooc', NULL, 1, 'approved', 1, NULL, NULL, NULL, '2026-08-05 16:50:51', '2026-08-05 16:50:51'),
(3, NULL, NULL, 'umum', 'Dalihan Na Tolu', 'Filosofi kehidupan masyarakat Batak yang menjadi pedoman dalam keseharian.', 'https://lh3.googleusercontent.com/aida-public/AB6AXuC7FB0juiMPN2M1-s8FWXpY0Q26Ek_9OK3C6xInToQKxmImWxvh5jL9DYiE6GNiJXrKLeqCosaNEd83WFNst6-Ugk-2L7ljUx30xn5_1HbOrDKQTscm6xlvm5ANGES0Q7REmiG0_TlWxtczn_whN6PhZ31cqsx47KAZnlPGvHeuHs_miWovPkQbujPHq7Ul7-YGjyyXJbpUmANMfpvBlVCBzTu3T63xfReWfuh21kijtyPgdgX1q84', NULL, 1, 'approved', 1, NULL, NULL, NULL, '2026-08-05 16:50:51', '2026-08-05 16:50:51'),
(4, 6, NULL, 'umum', 'Dalihan Na Tolu: Sistem Kekerabatan Masyarakat Batak Toba', 'Dalihan Na Tolu adalah sistem kekerabatan dasar dalam masyarakat Batak Toba yang mengatur hubungan dan peran sosial melalui tiga unsur utama, yaitu Somba Marhula-hula (menghormati pihak keluarga istri), Manat Mardongan Tubu (berhati-hati dan menjaga hubungan dengan teman semarga), serta Elek Marboru (mengasihi dan menyayangi pihak boru atau anak perempuan). Sistem ini menjadi landasan penting dalam kehidupan sosial dan adat masyarakat Batak Toba.', 'https://ik.imagekit.io/tvlk/blog/2025/06/shutterstock_2316607715-1.png?tr=q-70,c-at_max,w-500,h-250,dpr-2', 'https://www.traveloka.com/id-id/explore/activities/mengenal-adat-batak-toba-ta/604590', 1, 'approved', 1, NULL, NULL, NULL, '2026-09-11 07:13:08', '2026-09-11 07:13:08'),
(5, 6, NULL, 'umum', 'Mengenal Siraja Batak dan Asal-Usul Leluhur', 'Siraja Batak merupakan tokoh leluhur yang memiliki tempat penting dalam cerita asal-usul dan silsilah masyarakat Batak. Kisah tentang Siraja Batak menjadi bagian dari warisan budaya yang diturunkan dari generasi ke generasi. Melalui cerita leluhur dan tarombo, masyarakat Batak mengenal hubungan keturunan, marga, serta ikatan kekerabatan yang menjadi bagian penting dalam kehidupan adat dan budaya Batak.', 'https://pagaralampos.disway.id/upload/5e4253401d2c05960d49751e7ea7711f.jpeg', 'https://bpodt.kemenpar.go.id/jejak-batak-siraja-batak/', 1, 'approved', 6, NULL, NULL, NULL, '2026-09-11 07:53:40', '2026-09-11 08:41:17'),
(6, 6, NULL, 'umum', 'Horja Bius: Merawat Tradisi Budaya Batak', 'Horja Bius merupakan salah satu tradisi masyarakat Batak yang mencerminkan kebersamaan, nilai adat, penghormatan terhadap leluhur, serta hubungan masyarakat dengan lingkungan. Tradisi ini menjadi bagian dari warisan budaya yang terus dijaga dan diperkenalkan kepada generasi berikutnya.', 'https://tse2.mm.bing.net/th/id/OIP.CAaCHqPzJjnBIp-wM-q4ngHaE7?r=0&pid=Api', NULL, 1, 'approved', 2, NULL, NULL, NULL, '2026-09-11 08:26:30', '2026-09-11 08:28:17'),
(7, 6, NULL, 'umum', 'Napak Tilas Perjuangan Sisingamangaraja di Bakkara', 'Bakkara merupakan wilayah yang memiliki nilai sejarah penting bagi masyarakat Batak Toba karena dikenal sebagai tempat kelahiran Sisingamangaraja. Artikel ini mengisahkan jejak perjuangan Sisingamangaraja melawan penjajahan Belanda, serta berbagai peninggalan dan tempat bersejarah seperti Tombak Sulu-Sulu, Istana Sisingamangaraja, Aek Sipangolu, dan Rumah Bolon. Kisah tersebut memperlihatkan hubungan antara leluhur, sejarah, budaya, dan alam Bakkara yang diwariskan kepada generasi berikutnya.', 'https://ik.imagekit.io/goodid/gnfi/uploads/articles/large-istanapng-99089f3c62320be57d6d5acf8e0f398d.png', 'https://bpodt.kemenpar.go.id/napak-tilas-perjuangan-sisingamangaraja-di-bakkara/', 1, 'approved', 1, NULL, NULL, NULL, '2026-09-11 09:08:10', '2026-09-11 09:08:10'),
(8, 6, NULL, 'umum', 'Mengenal Suku Batak Pakpak: Asal-Usul dan Kehidupan', 'Artikel ini membahas Suku Batak Pakpak, mulai dari asal-usul dan sejarah leluhurnya hingga kehidupan masyarakatnya. Pembahasan mencakup marga, adat istiadat, tradisi, serta sistem kekerabatan Sulang Silima yang menjadi bagian penting dari identitas budaya Pakpak.', 'https://pagaralampos.disway.id/upload/3f73c8f9eeb7275b8e3c740dd41a5ced.jpg', 'https://www.indonesiancivil.com/artikel/mengenal-suku-batak-pakpak-asal-usul-dan-kehidupan', 1, 'approved', 1, NULL, NULL, NULL, '2026-09-11 09:26:00', '2026-09-11 09:26:00'),
(9, 6, 30, 'marga', 'Diantara Raja Sumba & Sihombing-Simamora', 'Artikel ini membahas kisah Boru Lontung serta hubungan kekerabatan antara Raja Lontung, Raja Sumba II, dan dua marga yaitu Sihombing dan Simamora. Artikel menguraikan beberapa versi mengenai hubungan pernikahan, silsilah, posisi kedua marga dalam adat, serta tradisi yang berkaitan dengan Ompu i Lontung. Pembahasan juga mencakup Batu Pauseang di Tipang Bakkara yang menjadi bagian dari cerita dan bukti material dalam tradisi yang dibahas.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSRoIx7eAroj76EBphW73WA4WbIp-fnitP8FGfDtIkiww&s=10', 'https://sejarahbatak.com/marga-simamora-marga-sihombing-tipang-bakkara-tradisi-batak-pomparan-ompu-i-lontung-raja-lontung-raja-sumba-ii-batu-pauseang/', 1, 'approved', 2, NULL, NULL, NULL, '2026-09-16 09:27:08', '2026-09-16 09:27:34'),
(10, 6, NULL, 'umum', 'Sipaha Lima, Tradisi Leluhur Batak Mensyukuri Hasil Panen', 'Sipaha Lima merupakan tradisi leluhur masyarakat Parmalim yang dilaksanakan sebagai ungkapan syukur atas hasil panen dan berkah dari Mulajadi Nabolon. Tradisi ini dilaksanakan setiap tahun dan melibatkan berbagai prosesi adat, doa, persembahan, musik tradisional Ogung Sabangunan, serta tortor. Tradisi ini juga mencerminkan penghormatan terhadap leluhur, alam, dan pelestarian budaya Batak.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcR2sMxyk9n2w5thXj3rMdnnjPDeLtNAtvt9eJn79k5OMQ&s=10', 'https://batakpedia.org/sipaha-lima-tradisi-leluhur-batak-mensyukuri-hasil-panen/?utm_source=chatgpt.com', 1, 'approved', 1, NULL, NULL, NULL, '2026-09-16 09:37:39', '2026-09-16 09:37:39');
